import '../../../core/api/api_client.dart';
import '../domain/life_event.dart'; import '../domain/life_event_repository.dart';
class LifeEventApiRepository implements LifeEventRepository { const LifeEventApiRepository(this.client); final ApiClient client; String _base(String p)=>'/v1/birth-profiles/$p/life-events'; @override Future<List<LifeEvent>> list(String p,{LifeEventCategory? category}) async { final r=await client.get<Map<String,dynamic>>(_base(p),queryParameters:category==null?null:{'category':category.wire}); final v=r.data?['lifeEvents']; if(v is! List) throw const FormatException('Malformed Life Events.'); return v.map((e)=>LifeEvent.fromJson(Map<String,dynamic>.from(e as Map))).toList(growable:false); } Future<LifeEvent> _write(Future<dynamic> request) async { final r=await request; final v=r.data?['lifeEvent']; if(v is! Map) throw const FormatException('Malformed Life Event.'); return LifeEvent.fromJson(Map<String,dynamic>.from(v)); } @override Future<LifeEvent> create(String p,LifeEventInput i)=>_write(client.post<Map<String,dynamic>>(_base(p),data:i.toJson())); @override Future<LifeEvent> update(String p,String id,LifeEventInput i)=>_write(client.patch<Map<String,dynamic>>('${_base(p)}/$id',data:i.toJson())); @override Future<void> delete(String p,String id) async { await client.delete<Map<String,dynamic>>('${_base(p)}/$id'); } }
